def transform(grid):
    h, w = len(grid), len(grid[0])

    # For horizontal stripes, find the shortest repeating row pattern
    # consistent with every nonzero row.
    if all(len(set(row)) == 1 for row in grid):
        vals = [row[0] for row in grid]
        known = [r for r, v in enumerate(vals) if v != 0]
        if not known:
            return [row[:] for row in grid]

        period = None
        pattern = None
        for p in range(1, h + 1):
            colors = {}
            valid = True
            for r in known:
                k = r % p
                if k in colors and colors[k] != vals[r]:
                    valid = False
                    break
                colors[k] = vals[r]
            if valid:
                period, pattern = p, colors
                break

        out = []
        for r in range(h):
            color = pattern.get(r % period, 0)
            out.append([color] * w)
        return out

    # Complete the repeated diagonal pattern.
    n = max(h, w)
    candidates = []
    for sign in (1, -1):
        groups = {}
        conflicts = 0
        for r in range(h):
            for c in range(w):
                v = grid[r][c]
                if v:
                    k = (r + sign * c) % n
                    if k in groups and groups[k] != v:
                        conflicts += 1
                    else:
                        groups[k] = v
        candidates.append((conflicts, groups, sign))

    _, groups, sign = min(candidates, key=lambda x: x[0])
    return [[groups.get((r + sign * c) % n, grid[r][c]) for c in range(w)]
            for r in range(h)]
